DROP TABLE IF EXISTS objekte; DROP TABLE IF EXISTS bodenrichtwerte; CREATE TABLE zonen (zone_id TEXT PRIMARY KEY, zone_name TEXT, bundesland TEXT); CREATE TABLE bodenrichtwerte (id INTEGER PRIMARY KEY, zone_id TEXT REFERENCES zonen(zone_id), jahr INTEGER, wert_eur_qm REAL); CREATE TABLE objekte (id INTEGER PRIMARY KEY, user_id TEXT, bezeichnung TEXT, plz TEXT, bundesland TEXT, zone_id TEXT REFERENCES zonen(zone_id), wohnflaeche_qm REAL, baujahr INTEGER, erstellt_am TEXT);